// Read the persistent cursor from workflow static data. First run uses '0'
// (numeric) or '1970-01-01T00:00:00Z' (timestamp) — operator picks based on
// the cursor column type. Default-zero is safe: SELECT will return all rows
// on first run, which is intentional for a fresh sync.
const staticData = $getWorkflowStaticData('global');
const cursorColumn = $node['SET_DEFAULTS'].json['cursor_column'];
const isTimestampCursor = cursorColumn.includes('_at') || cursorColumn.includes('time');
const defaultCursor = isTimestampCursor ? '1970-01-01T00:00:00Z' : 0;
const lastCursor = staticData.lastCursor !== undefined ? staticData.lastCursor : defaultCursor;
return [{ json: { last_cursor: lastCursor, cursor_is_timestamp: isTimestampCursor } }];

// Advance the cursor to the highest value we just synced. Persisted across
// runs in workflow static data. Fail-safe: if no rows were synced this run,
// leave the cursor unchanged.
const staticData = $getWorkflowStaticData('global');
const cursorColumn = $node['SET_DEFAULTS'].json['cursor_column'];
const rows = $node['Fetch new Postgres rows'].json;
const rowsArray = Array.isArray(rows) ? rows : [rows];

if (rowsArray.length === 0 || !rowsArray[0][cursorColumn]) {
  return [{ json: { advanced: false, last_cursor: staticData.lastCursor } }];
}

const maxCursor = rowsArray.reduce((max, r) => {
  const v = r[cursorColumn];
  return (max === undefined || v > max) ? v : max;
}, undefined);

staticData.lastCursor = maxCursor;
return [{ json: { advanced: true, last_cursor: maxCursor, synced_count: rowsArray.length } }];
